import itertools
from collections import Counter


def _route(data, exact, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    node_masks = [0] * data["n"]
    for i, node in enumerate(required):
        node_masks[node] |= 1 << i

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    coupons = data["coupons"]
    initial = (source, node_masks[source], coupons)
    distances = {initial: data["start"]}
    queue = [(data["start"], source, node_masks[source], coupons)]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full
                and (not exact or remaining == 0)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            ordinary_time = depart + edge["duration"]
            options = [(ordinary_time, remaining)]
            if remaining:
                discounted_duration = max(
                    minimum_duration,
                    edge["duration"] - edge.get("discount", 0))
                options.append((depart + discounted_duration, remaining - 1))

            for next_time, next_remaining in options:
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | node_masks[next_node]
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask,
                                           next_remaining))

    return {"arrival": None}


def _build_route(exact, minimum_duration):
    return lambda data: _route(data, exact, minimum_duration)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000,
                          data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|"
                   + event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}

    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, []))
            if name in pins:
                versions = [v for v in versions if v == pins[name]]
            choices.append([-1] + versions)

        best_score = None
        best = None
        for vector in itertools.product(*choices):
            installed = {name: version for name, version in zip(names, vector)
                         if version != -1}
            if any(name not in installed
                   or not bounds[0] <= installed[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            rows = {}
            valid = True
            for name, version in installed.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                rows[name] = row
            edges = {name: [] for name in installed}
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if (target not in installed
                            or not dep["min"] <= installed[target] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                if name not in installed:
                    valid = False
                    break
                reachable.add(name)
                pending.extend(edges[name])
            if not valid or reachable != set(installed):
                continue

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in installed):
                continue

            score = tuple(vector)
            if best_score is None or score > best_score:
                best_score = score
                best = installed

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}

    return solve


def _build_component_08():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = Counter(job["group"] for job in selected)
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts[group] <= high:
                return False

        active_ends = []
        for job in sorted(selected,
                          key=lambda item: (item["start"], item["end"], item["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                return False
        return True

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        if k > len(jobs):
            return {"error": "impossible"}
        best_value = None
        best_ids = None
        for selected in itertools.combinations(jobs, k):
            if not feasible(selected, data):
                continue
            value = sum(job["value"] for job in selected)
            ids = tuple(sorted(job["id"] for job in selected))
            if (best_value is None or value > best_value
                    or (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


